<script>
import {games} from '$lib/data/games.js';import GameCard from '$lib/components/GameCard.svelte';
let search=$state(''),platform=$state('All platforms'),genre=$state('All genres'),status=$state('Any status'),sort=$state('Featured');
const platforms=$derived(['All platforms',...new Set(games.flatMap(g=>g.platforms??[]))]);const genres=$derived(['All genres',...new Set(games.flatMap(g=>g.genres??[]))]);
const filtered=$derived.by(()=>{let list=games.filter(g=>(!search.trim()||[g.title,g.shortDescription,...(g.genres??[])].join(' ').toLowerCase().includes(search.trim().toLowerCase()))&&(platform==='All platforms'||(g.platforms??[]).includes(platform))&&(genre==='All genres'||(g.genres??[]).includes(genre))&&(status==='Any status'||g.status===status));if(sort==='Title A–Z')list=[...list].sort((a,b)=>a.title.localeCompare(b.title));if(sort==='Release date')list=[...list].sort((a,b)=>(b.releaseDate??'').localeCompare(a.releaseDate??''));if(sort==='Price: low to high')list=[...list].sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sort==='Price: high to low')list=[...list].sort((a,b)=>(b.price??-Infinity)-(a.price??-Infinity));if(sort==='Featured')list=[...list].sort((a,b)=>Number(!!b.featured)-Number(!!a.featured));return list});
function reset(){search='';platform='All platforms';genre='All genres';status='Any status';sort='Featured'}
</script>
<svelte:head><title>Games — Frokyte Games</title><meta name="description" content="Explore games developed and published by Frokyte Games."/></svelte:head>
<main class="mx-auto max-w-[1440px] px-6 py-20 sm:px-10 lg:px-16 lg:py-28"><div class="max-w-3xl"><p class="text-xs font-bold uppercase tracking-wider text-primary">The catalog</p><h1 class="mt-5 text-5xl font-black sm:text-7xl">Our games.</h1><p class="mt-6 text-lg text-white/55">Explore the worlds, stories and experiences created and published by Frokyte Games.</p></div>
<section class="mt-14 rounded-lg border border-white/10 bg-[#151619] p-5 sm:p-7" aria-label="Game filters"><div class="grid gap-4 lg:grid-cols-[minmax(240px,2fr)_repeat(4,minmax(130px,1fr))]"><label class="form-control"><span class="mb-2 text-xs font-bold uppercase text-white/45">Search games</span><div class="relative"><i class="fa-solid fa-magnifying-glass absolute left-4 top-1/2 -translate-y-1/2 text-white/35"></i><input bind:value={search} type="search" placeholder="Title, genre..." class="input input-bordered w-full border-white/10 bg-black/20 pl-11 text-white"/></div></label><label class="form-control"><span class="mb-2 text-xs font-bold uppercase text-white/45">Platform</span><select bind:value={platform} class="select select-bordered border-white/10 bg-black/20 text-white">{#each platforms as p}<option>{p}</option>{/each}</select></label><label class="form-control"><span class="mb-2 text-xs font-bold uppercase text-white/45">Genre</span><select bind:value={genre} class="select select-bordered border-white/10 bg-black/20 text-white">{#each genres as g}<option>{g}</option>{/each}</select></label><label class="form-control"><span class="mb-2 text-xs font-bold uppercase text-white/45">Availability</span><select bind:value={status} class="select select-bordered border-white/10 bg-black/20 text-white">{#each ['Any status','Released','Coming soon','In development'] as s}<option>{s}</option>{/each}</select></label><label class="form-control"><span class="mb-2 text-xs font-bold uppercase text-white/45">Sort by</span><select bind:value={sort} class="select select-bordered border-white/10 bg-black/20 text-white">{#each ['Featured','Release date','Title A–Z','Price: low to high','Price: high to low'] as s}<option>{s}</option>{/each}</select></label></div><div class="mt-5 flex justify-between border-t border-white/10 pt-4 text-sm"><span class="text-white/45">{filtered.length} games</span><button class="btn btn-ghost btn-sm" onclick={reset}>Clear filters</button></div></section>
{#if filtered.length}<section class="mt-10 grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{#each filtered as game (game.slug)}<GameCard {game}/>{/each}</section>{:else}<section class="mt-10 rounded-lg border border-dashed border-white/15 px-6 py-20 text-center"><i class="fa-solid fa-gamepad text-3xl text-white/25"></i><h2 class="mt-5 text-2xl font-bold">{games.length?'No games found':'The catalog is taking shape.'}</h2><p class="mx-auto mt-3 max-w-lg text-sm text-white/45">{games.length?'Try changing your search or filters.':'There are no public game listings yet. New titles will appear here when announced.'}</p>{#if games.length}<button class="btn btn-outline mt-6" onclick={reset}>Reset filters</button>{/if}</section>{/if}</main>
